//! End-to-end tests that run the pdf2png binary on PDFs generated by the tests.
//! Rendering tests need libpdfium in the repository root and are skipped without it (e.g. on CI).

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

/// Builds a minimal valid PDF with one Helvetica text line per page.
fn make_pdf(pages: &[&str]) -> Vec<u8> {
    let mut objects = vec![
        "<< /Type /Catalog /Pages 2 0 R >>".to_string(),
        format!(
            "<< /Type /Pages /Kids [{}] /Count {} >>",
            (0..pages.len()).map(|i| format!("{} 0 R", 4 + 2 * i)).collect::<Vec<_>>().join(" "),
            pages.len()
        ),
        "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>".to_string(),
    ];
    for (i, text) in pages.iter().enumerate() {
        let content = format!("BT /F1 24 Tf 72 720 Td ({text}) Tj ET");
        objects.push(format!(
            "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R >> >> /Contents {} 0 R >>",
            5 + 2 * i
        ));
        objects.push(format!("<< /Length {} >>\nstream\n{content}\nendstream", content.len()));
    }
    write_pdf(&objects)
}

/// Serializes the objects (numbered from 1) with a correct cross-reference table.
fn write_pdf(objects: &[String]) -> Vec<u8> {
    let mut pdf = b"%PDF-1.4\n".to_vec();
    let mut offsets = Vec::new();
    for (i, object) in objects.iter().enumerate() {
        offsets.push(pdf.len());
        pdf.extend_from_slice(format!("{} 0 obj\n{object}\nendobj\n", i + 1).as_bytes());
    }
    let xref_offset = pdf.len();
    pdf.extend_from_slice(format!("xref\n0 {}\n0000000000 65535 f \n", objects.len() + 1).as_bytes());
    for offset in offsets {
        pdf.extend_from_slice(format!("{offset:010} 00000 n \n").as_bytes());
    }
    pdf.extend_from_slice(
        format!("trailer\n<< /Size {} /Root 1 0 R >>\nstartxref\n{xref_offset}\n%%EOF\n", objects.len() + 1).as_bytes(),
    );
    pdf
}

fn write_temp_pdf(dir: &Path, name: &str, bytes: &[u8]) -> PathBuf {
    let path = dir.join(name);
    std::fs::write(&path, bytes).unwrap();
    path
}

fn run(args: &[&std::ffi::OsStr]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_pdf2png")).args(args).output().unwrap()
}

/// The repository root, if it contains the pdfium library needed for rendering.
fn pdfium_dir() -> Option<PathBuf> {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let found = ["libpdfium.dylib", "libpdfium.so", "pdfium.dll"].iter().any(|lib| dir.join(lib).exists());
    if !found {
        eprintln!("skipped: no pdfium library in {}", dir.display());
    }
    found.then_some(dir)
}

#[test]
fn text_only_extracts_text_of_every_page() {
    let dir = tempfile::tempdir().unwrap();
    let pdf = write_temp_pdf(dir.path(), "t.pdf", &make_pdf(&["Hello first page", "Second page here"]));

    let output = run(&["--text-only".as_ref(), pdf.as_os_str()]);

    assert!(output.status.success(), "stderr: {}", String::from_utf8_lossy(&output.stderr));
    let text = String::from_utf8(output.stdout).unwrap();
    assert!(text.contains("Hello first page"), "got: {text:?}");
    assert!(text.contains("Second page here"), "got: {text:?}");
}

/// Regression test for RUSTSEC-2026-0187: lopdf < 0.42 overflowed the stack on deeply nested objects.
#[test]
fn text_only_rejects_deeply_nested_pdf_without_crashing() {
    let depth = 100_000;
    let nested = format!("{}{}", "[".repeat(depth), "]".repeat(depth));
    let objects = vec![
        "<< /Type /Catalog /Pages 2 0 R /Evil 3 0 R >>".to_string(),
        "<< /Type /Pages /Kids [] /Count 0 >>".to_string(),
        nested,
    ];
    let dir = tempfile::tempdir().unwrap();
    let pdf = write_temp_pdf(dir.path(), "nested.pdf", &write_pdf(&objects));

    let output = run(&["--text-only".as_ref(), pdf.as_os_str()]);

    // a stack overflow aborts the process via a signal, which leaves no exit code
    assert!(
        output.status.code().is_some(),
        "pdf2png crashed: {:?}, stderr: {}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
}

#[test]
fn converts_every_page_to_png() {
    let Some(lib_dir) = pdfium_dir() else { return };
    let dir = tempfile::tempdir().unwrap();
    let pdf = write_temp_pdf(dir.path(), "doc.pdf", &make_pdf(&["one", "two"]));

    let output = run(&[
        pdf.as_os_str(),
        "-o".as_ref(), dir.path().as_os_str(),
        "-l".as_ref(), lib_dir.as_os_str(),
        "-r".as_ref(), "200".as_ref(),
    ]);

    assert!(output.status.success(), "stderr: {}", String::from_utf8_lossy(&output.stderr));
    assert_eq!(String::from_utf8(output.stdout).unwrap(), "2");
    for name in ["doc-0.png", "doc-1.png"] {
        let image = image::open(dir.path().join(name)).unwrap();
        assert!(image.width() <= 200 && image.height() <= 200, "{name} is {}x{}", image.width(), image.height());
        assert!(image.width() == 200 || image.height() == 200, "{name} is {}x{}", image.width(), image.height());
    }
    let leftovers: Vec<_> = std::fs::read_dir(dir.path())
        .unwrap()
        .filter_map(|e| e.ok())
        .filter(|e| e.file_name().to_string_lossy().ends_with(".tmp"))
        .collect();
    assert!(leftovers.is_empty(), "temporary files left behind: {leftovers:?}");
}

#[test]
fn converts_only_the_requested_page_range() {
    let Some(lib_dir) = pdfium_dir() else { return };
    let dir = tempfile::tempdir().unwrap();
    let pdf = write_temp_pdf(dir.path(), "doc.pdf", &make_pdf(&["one", "two", "three"]));

    let output = run(&[
        pdf.as_os_str(),
        "-o".as_ref(), dir.path().as_os_str(),
        "-l".as_ref(), lib_dir.as_os_str(),
        "-r".as_ref(), "100".as_ref(),
        "--from-page".as_ref(), "1".as_ref(),
        "--to-page".as_ref(), "1".as_ref(),
    ]);

    assert!(output.status.success(), "stderr: {}", String::from_utf8_lossy(&output.stderr));
    assert_eq!(String::from_utf8(output.stdout).unwrap(), "3");
    assert!(!dir.path().join("doc-0.png").exists());
    assert!(dir.path().join("doc-1.png").exists());
    assert!(!dir.path().join("doc-2.png").exists());
}

#[test]
fn first_page_only_writes_file_without_index_suffix() {
    let Some(lib_dir) = pdfium_dir() else { return };
    let dir = tempfile::tempdir().unwrap();
    let pdf = write_temp_pdf(dir.path(), "doc.pdf", &make_pdf(&["one", "two"]));

    let output = run(&[
        pdf.as_os_str(),
        "-f".as_ref(),
        "-o".as_ref(), dir.path().as_os_str(),
        "-l".as_ref(), lib_dir.as_os_str(),
        "-r".as_ref(), "100".as_ref(),
    ]);

    assert!(output.status.success(), "stderr: {}", String::from_utf8_lossy(&output.stderr));
    assert!(dir.path().join("doc.png").exists());
    assert!(!dir.path().join("doc-1.png").exists());
}
